const Maker = (() => {
  const state = { filaments: [], materials: [], settings: {}, quotes: [], users: [], projects: [], tasks: [], quotesPage: 0, editing: null, quoteProjectId: null };
  const isAdmin = () => (localStorage.getItem('userRol') || '').toUpperCase() === 'ADMIN';
  const money = value => new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN' }).format(Number(value || 0));
  const num = value => Number(value || 0).toLocaleString('es-MX', { maximumFractionDigits: 3 });
  const esc = value => Utils.esc(value == null ? '' : String(value));
  const setting = key => Number(state.settings[key] ?? 0);

  async function init() {
    bindTabs();
    try {
      const [filaments, materials, configs] = await Promise.all([
        API.get('/maker/filamentos'), API.get('/maker/materiales'), API.get('/maker/configuracion/publica')
      ]);
      state.filaments = filaments || []; state.materials = isAdmin() ? await API.get('/maker/materiales?todos=true') : (materials || []);
      (configs || []).forEach(c => state.settings[c.clave] = c.valor);
       renderCalculator(); renderQuotes(); renderFilaments(); renderMaterials(); renderSettings();
       bindCalculator();
       bindFinalPrice();
       await loadWorkspace();
    } catch (e) { Utils.showToast('No se pudo cargar Maker: ' + e.message, 'error'); renderCalculator(); }
  }

  function bindTabs() {
    document.querySelectorAll('[data-maker-tab]').forEach(tab => tab.addEventListener('click', () => {
      document.querySelectorAll('[data-maker-tab]').forEach(t => t.classList.remove('active'));
      document.querySelectorAll('.maker-tab-panel').forEach(p => p.classList.add('d-none'));
      tab.classList.add('active'); document.getElementById('maker-' + tab.dataset.makerTab)?.classList.remove('d-none');
      if (tab.dataset.makerTab === 'quotes') loadQuotes();
      if (tab.dataset.makerTab === 'projects') loadProjects();
      if (tab.dataset.makerTab === 'tasks') loadTasks();
    }));
  }

  function renderCalculator() {
    document.getElementById('maker-calculator').innerHTML = `
      <div class="maker-grid">
        <div class="panel-card maker-form-card">
          <div class="maker-section-heading"><div><span class="maker-step">01</span><h5>Datos de la cama</h5><small>Captura el estimado de tu slicer</small></div><i class="fas fa-print"></i></div>
          <div class="row g-3">
            <div class="col-12"><label class="form-label">Descripción</label><input id="mkDescripcion" class="form-control" placeholder="Ej. Llavero personalizado"></div>
            <div class="col-md-4"><label class="form-label">Tipo de impresión</label><select id="mkModo" class="form-select"><option value="MONOCOLOR">Monocolor</option><option value="MULTICOLOR">Multicolor</option></select></div>
            <div class="col-md-4"><label class="form-label">Gramos netos <span class="text-danger">*</span></label><input id="mkGramos" type="number" min="0.001" step="0.001" class="form-control" placeholder="0.00"></div>
            <div class="col-md-4"><label class="form-label">Horas de impresión <span class="text-danger">*</span></label><input id="mkHoras" type="number" min="0.01" step="0.01" class="form-control" placeholder="0.00"></div>
            <div class="col-md-4"><label class="form-label">Piezas por cama <span class="text-danger">*</span></label><input id="mkPiezas" type="number" min="1" step="1" class="form-control" value="1"></div>
            <div class="col-md-4"><label class="form-label">Consumo eléctrico (kW)</label><input id="mkKw" type="number" min="0" step="0.001" class="form-control" value="${setting('CONSUMO_KW') || 0.1}"></div>
            <div class="col-md-4"><label class="form-label">Costo kWh (MXN)</label><input id="mkKwh" type="number" min="0" step="0.01" class="form-control" value="${setting('COSTO_KWH') || 3.5}"></div>
            <div class="col-md-4"><label class="form-label">Precio a visualizar</label><select id="mkPriceType" class="form-select"><option value="PUBLICO">Público · ${(setting('MARGEN_PUBLICO') * 100 || 50).toFixed(0)}%</option><option value="MAYOREO">Mayoreo · ${(setting('MARGEN_MAYOREO') * 100 || 35).toFixed(0)}%</option><option value="DISTRIBUIDOR">Distribuidor · ${(setting('MARGEN_DISTRIBUIDOR') * 100 || 20).toFixed(0)}%</option></select></div>
            <div class="col-12" id="mkColorFields"><label class="form-label">Cambios de color</label><input id="mkCambios" type="number" min="0" step="1" class="form-control" value="0"><div class="form-text">Se aplica purga configurable por cambio en modo multicolor.</div></div>
          </div>
          <div class="maker-section-heading mt-4"><div><span class="maker-step">02</span><h5>Filamentos</h5><small>Distribuye los gramos de la cama por color</small></div><button class="btn btn-sm btn-outline-primary" id="mkAddFilament"><i class="fas fa-plus me-1"></i>Agregar color</button></div>
          <div id="mkFilamentRows"></div>
          <div class="maker-section-heading mt-4"><div><span class="maker-step">03</span><h5>Productos extra</h5><small>Accesorios manuales por cama</small></div><button class="btn btn-sm btn-outline-primary" id="mkAddExtra"><i class="fas fa-plus me-1"></i>Agregar extra</button></div>
          <div id="mkExtraRows" class="maker-extra-list"></div>
          <div class="maker-form-actions"><button class="btn btn-primary px-4" id="mkCalculate"><i class="fas fa-wand-magic-sparkles me-2"></i>Calcular y guardar</button><button class="btn btn-light" id="mkClear">Limpiar</button></div>
        </div>
        <div class="maker-result-card" id="mkResult"><div class="maker-result-empty"><i class="fas fa-chart-line"></i><h5>Tu resumen aparecerá aquí</h5><p>Completa los datos de la cama para obtener el costo por pieza y el precio de venta.</p></div></div>
      </div>`;
    addFilamentRow(); addExtraRow(false);
    document.getElementById('mkModo').addEventListener('change', e => { document.getElementById('mkColorFields').style.display = e.target.value === 'MULTICOLOR' ? '' : 'none'; });
    document.getElementById('mkModo').dispatchEvent(new Event('change'));
  }

  function filamentOptions() { return '<option value="">Selecciona un filamento</option>' + state.filaments.map(f => `<option value="${f.id}">${esc(f.nombre)} · ${esc(f.color || 'Sin color')} · ${money(f.precioKilo)}/kg</option>`).join(''); }
  function addFilamentRow() {
    const box = document.getElementById('mkFilamentRows'); if (!box) return;
    const row = document.createElement('div'); row.className = 'maker-line-row maker-filament-row'; row.innerHTML = `<div class="maker-line-index">${box.children.length + 1}</div><select class="form-select mk-filament">${filamentOptions()}</select><input class="form-control mk-filament-grams" type="number" min="0.001" step="0.001" placeholder="Gramos"><button class="btn btn-icon maker-remove-line" type="button" title="Quitar"><i class="fas fa-xmark"></i></button>`;
    row.querySelector('.maker-remove-line').addEventListener('click', () => { if (box.children.length > 1) { row.remove(); refreshIndexes(box); } else Utils.showToast('Debe existir al menos un filamento', 'warning'); }); box.appendChild(row);
  }
  function addExtraRow(initial = true) {
    const box = document.getElementById('mkExtraRows'); if (!box) return;
    if (!initial && box.children.length) return;
    const row = document.createElement('div'); row.className = 'maker-line-row maker-extra-row'; row.innerHTML = `<input class="form-control mk-extra-name" placeholder="Ej. Argolla"><input class="form-control mk-extra-qty" type="number" min="0.01" step="0.01" value="1" placeholder="Cant."><input class="form-control mk-extra-price" type="number" min="0" step="0.01" placeholder="Precio unitario"><span class="maker-extra-total">$0.00</span><button class="btn btn-icon maker-remove-line" type="button" title="Quitar"><i class="fas fa-xmark"></i></button>`;
    row.querySelectorAll('input').forEach(input => input.addEventListener('input', () => { row.querySelector('.maker-extra-total').textContent = money(Number(row.querySelector('.mk-extra-qty').value) * Number(row.querySelector('.mk-extra-price').value)); })); row.querySelector('.maker-remove-line').addEventListener('click', () => row.remove()); box.appendChild(row);
  }
  function refreshIndexes(box) { [...box.children].forEach((row, i) => row.querySelector('.maker-line-index').textContent = i + 1); }
  function bindCalculator() {
    document.getElementById('mkAddFilament')?.addEventListener('click', () => addFilamentRow()); document.getElementById('mkAddExtra')?.addEventListener('click', () => addExtraRow(true));
    document.getElementById('mkClear')?.addEventListener('click', () => { renderCalculator(); bindCalculator(); }); document.getElementById('mkCalculate')?.addEventListener('click', calculate);
  }
  function bindFinalPrice() { if (state.finalPriceBound) return; state.finalPriceBound = true; document.addEventListener('click', async e => { const button = e.target.closest('#mkSaveFinalPrice'); if (!button) return; const value = Number(button.closest('.maker-sale-card, #makerDetailBody')?.querySelector('#mkFinalPrice')?.value || document.getElementById('mkFinalPrice')?.value); if (!Number.isFinite(value) || value < 0) return Utils.showToast('Captura un precio final válido', 'warning'); button.disabled = true; try { const quote = await API.request('/maker/cotizaciones/' + button.dataset.quoteId + '/precio-final', { method: 'PATCH', body: JSON.stringify({ precioPiezaFinal: value }) }); renderResult(quote); Utils.showToast('Precio final actualizado', 'success'); } catch (error) { Utils.showToast(error.message, 'error'); } finally { button.disabled = false; } }); }
  function collect() {
    const filamentos = [...document.querySelectorAll('.maker-filament-row')].map(r => ({ filamentoId: Number(r.querySelector('.mk-filament').value), gramos: Number(r.querySelector('.mk-filament-grams').value) })).filter(x => x.filamentoId && x.gramos > 0);
    const extras = [...document.querySelectorAll('.maker-extra-row')].map(r => ({ nombre: r.querySelector('.mk-extra-name').value.trim(), cantidad: Number(r.querySelector('.mk-extra-qty').value), precioUnitario: Number(r.querySelector('.mk-extra-price').value) })).filter(x => x.nombre && x.cantidad > 0);
    return { descripcion: document.getElementById('mkDescripcion').value.trim(), modo: document.getElementById('mkModo').value, gramosNetos: Number(document.getElementById('mkGramos').value), horasImpresion: Number(document.getElementById('mkHoras').value), piezasPorCama: Number(document.getElementById('mkPiezas').value), consumoKw: Number(document.getElementById('mkKw').value), costoKwh: Number(document.getElementById('mkKwh').value), cambiosColor: Number(document.getElementById('mkCambios').value || 0), tipoPrecio: document.getElementById('mkPriceType')?.value || 'PUBLICO', proyectoId: state.quoteProjectId, filamentos, extras };
  }
  async function calculate() {
    const data = collect(); const totalGrams = data.filamentos.reduce((sum, f) => sum + f.gramos, 0);
    if (!data.gramosNetos || !data.horasImpresion || !data.piezasPorCama || !data.filamentos.length) { Utils.showToast('Completa gramos, horas, piezas y al menos un filamento', 'warning'); return; }
    if (Math.abs(totalGrams - data.gramosNetos) > 0.01) { Utils.showToast(`Los gramos de filamentos (${num(totalGrams)}) deben coincidir con los gramos netos (${num(data.gramosNetos)})`, 'warning'); return; }
    const button = document.getElementById('mkCalculate'); button.disabled = true;
    try { const response = await API.post('/maker/cotizaciones', data); renderResult(response); Utils.showToast('Cotización guardada correctamente', 'success'); }
    catch (e) { Utils.showToast('No se pudo guardar: ' + e.message, 'error'); } finally { button.disabled = false; }
  }
  function renderResult(q) {
    document.getElementById('mkResult').innerHTML = `<div class="maker-result-top"><div><span class="maker-result-label">COTIZACIÓN ${esc(q.folio)}</span><h4>${esc(q.descripcion || 'Impresión 3D')}</h4></div><span class="maker-price-pill">${esc(q.tipoPrecio)}</span></div><div class="maker-metric-grid"><div><span>Material total</span><strong>${num(q.gramosTotales)} g</strong><small>${num(q.gramosMerma)} g de merma</small></div><div><span>Costo de cama</span><strong>${money(q.costoCama)}</strong><small>${money(q.costoPieza)} por pieza</small></div><div><span>Electricidad</span><strong>${money(q.costoElectricidad)}</strong><small>${num(q.horasImpresion)} h · ${num(q.consumoKw)} kW</small></div><div><span>Productos extra</span><strong>${money(q.costoExtras)}</strong><small>Incluidos en el costo</small></div></div><div class="maker-sale-card"><span>Precio sugerido</span><strong>${money(q.precioPieza)} <small>/ pieza</small></strong><div>${money(q.precioCama)} por cama - margen ${(Number(q.margen) * 100).toFixed(0)}%</div><label class="maker-final-price-label">Precio final ajustado</label><div class="input-group maker-final-price-group"><span class="input-group-text">$</span><input id="mkFinalPrice" class="form-control" type="number" min="0" step="0.01" value="${q.precioPiezaFinal ?? q.precioPieza}"><button class="btn btn-primary" id="mkSaveFinalPrice" data-quote-id="${q.id}" title="Guardar precio final"><i class="fas fa-check"></i></button></div><small class="maker-final-price-help">Puedes redondear o ajustar el precio por pieza.</small></div><div class="maker-breakdown"><div><span>Filamento</span><b>${money(q.costoMaterial)}</b></div><div><span>Electricidad</span><b>${money(q.costoElectricidad)}</b></div><div><span>Extras</span><b>${money(q.costoExtras)}</b></div><div class="total"><span>Total cama</span><b>${money(q.costoCama)}</b></div></div>`;
  }

  async function loadQuotes() { const box = document.getElementById('maker-quotes'); box.innerHTML = '<div class="maker-loading">Cargando cotizaciones...</div>'; try { const data = await API.get('/maker/cotizaciones?page=' + state.quotesPage + '&size=20'); renderQuotes(data); } catch (e) { box.innerHTML = `<div class="empty-state"><p>${esc(e.message)}</p></div>`; } }
  function renderQuotes(data = { content: [] }) { const list = data.content || []; document.getElementById('maker-quotes').innerHTML = `<div class="maker-toolbar"><div><h5>Historial de cotizaciones</h5><small>Consulta y administra tus cálculos guardados</small></div><button class="btn btn-primary" id="mkNewQuote"><i class="fas fa-plus me-1"></i>Nueva cotización</button></div><div class="panel-card overflow-hidden"><div class="table-responsive"><table class="table table-custom maker-table"><thead><tr><th>Folio</th><th>Descripción</th><th>Fecha</th><th>Piezas</th><th>Tipo</th><th>Precio/pieza</th><th></th></tr></thead><tbody>${list.length ? list.map(q => `<tr><td><strong>${esc(q.folio)}</strong></td><td>${esc(q.descripcion || 'Sin descripción')}</td><td>${Utils.formatDateTime(q.fecha)}</td><td>${q.piezasPorCama}</td><td><span class="maker-type-badge">${esc(q.tipoPrecio)}</span></td><td class="maker-money">${money(q.precioPiezaFinal ?? q.precioPieza)}</td><td>${kebab(q.id, 'quote')}</td></tr>`).join('') : `<tr><td colspan="7"><div class="empty-state"><i class="fas fa-receipt"></i><p>Aún no hay cotizaciones guardadas</p></div></td></tr>`}</tbody></table></div>${pagination(data, 'quotes')}</div>`; bindKebabs(); document.getElementById('mkNewQuote')?.addEventListener('click', () => document.querySelector('[data-maker-tab="calculator"]')?.click()); }
  function pagination(data, type) { return data.totalPages > 1 ? `<div class="maker-pagination"><small>Página ${data.number + 1} de ${data.totalPages} · ${data.totalElements} registros</small><div><button class="btn btn-sm btn-light" ${data.first ? 'disabled' : ''} data-maker-page="prev"><i class="fas fa-chevron-left"></i></button><button class="btn btn-sm btn-light" ${data.last ? 'disabled' : ''} data-maker-page="next"><i class="fas fa-chevron-right"></i></button></div></div>` : ''; }
  function kebab(id, type) { return `<div class="dropdown text-end"><button class="btn btn-icon" data-bs-toggle="dropdown" aria-label="Acciones"><i class="fas fa-ellipsis-vertical"></i></button><ul class="dropdown-menu dropdown-menu-end"><li><button class="dropdown-item maker-action" data-action="view-${type}" data-id="${id}"><i class="fas fa-eye me-2"></i>Ver detalle</button></li><li><button class="dropdown-item text-danger maker-action" data-action="delete-${type}" data-id="${id}"><i class="fas fa-trash me-2"></i>Eliminar</button></li></ul></div>`; }
  function bindKebabs() { document.querySelectorAll('.maker-action').forEach(b => b.addEventListener('click', async () => { const id = Number(b.dataset.id); if (b.dataset.action === 'view-quote') { const q = await API.get('/maker/cotizaciones/' + id); showDetail(q); } else if (b.dataset.action === 'delete-quote' && await Utils.confirmAction('¿Eliminar esta cotización?', 'Confirmar', 'Eliminar')) { await API.del('/maker/cotizaciones/' + id); Utils.showToast('Cotización eliminada', 'success'); loadQuotes(); } })); document.querySelectorAll('[data-maker-page]').forEach(b => b.addEventListener('click', () => { if (!b.disabled) { state.quotesPage += b.dataset.makerPage === 'next' ? 1 : -1; loadQuotes(); } })); }
  function showDetail(q) { document.getElementById('makerDetailBody').innerHTML = `<div class="maker-detail-grid"><div><small>Folio</small><strong>${esc(q.folio)}</strong></div><div><small>Fecha</small><strong>${Utils.formatDateTime(q.fecha)}</strong></div><div><small>Material</small><strong>${num(q.gramosTotales)} g</strong></div><div><small>Costo cama</small><strong>${money(q.costoCama)}</strong></div><div><small>Precio sugerido / final</small><strong class="text-primary">${money(q.precioPiezaFinal ?? q.precioPieza)}</strong><div class="input-group input-group-sm mt-2"><span class="input-group-text">$</span><input id="mkFinalPrice" class="form-control" type="number" min="0" step="0.01" value="${q.precioPiezaFinal ?? q.precioPieza}"><button class="btn btn-primary" id="mkSaveFinalPrice" data-quote-id="${q.id}" title="Guardar precio final"><i class="fas fa-check"></i></button></div></div><div><small>Tipo de precio</small><strong>${esc(q.tipoPrecio)}</strong></div></div><hr><h6>Filamentos</h6><ul class="maker-detail-list">${q.filamentos.map(f => `<li><span>${esc(f.nombre)} · ${esc(f.color || '')}</span><b>${num(f.gramos)} g · ${money(f.costo)}</b></li>`).join('')}</ul><h6 class="mt-3">Extras</h6><ul class="maker-detail-list">${q.extras.length ? q.extras.map(e => `<li><span>${esc(e.nombre)} × ${num(e.cantidad)}</span><b>${money(e.importe)}</b></li>`).join('') : '<li><span>Sin extras</span><b>$0.00</b></li>'}</ul>`; new bootstrap.Modal(document.getElementById('makerDetailModal')).show(); }

  function renderFilaments() { const admin = isAdmin(); document.getElementById('maker-filaments').innerHTML = `<div class="maker-toolbar"><div><h5>Catálogo de filamentos</h5><small>Precios y colores disponibles para tus cálculos</small></div>${admin ? '<button class="btn btn-primary" id="mkNewFilament"><i class="fas fa-plus me-1"></i>Nuevo filamento</button>' : ''}</div><div class="panel-card overflow-hidden"><div class="table-responsive"><table class="table table-custom maker-table"><thead><tr><th>Filamento</th><th>Material</th><th>Marca</th><th>Color</th><th>Precio/kg</th><th>Estado</th><th></th></tr></thead><tbody>${state.filaments.length ? state.filaments.map(f => `<tr><td><strong>${esc(f.nombre)}</strong></td><td>${esc(f.material)}</td><td>${esc(f.marca || '-')}</td><td><span class="maker-color-dot" style="--maker-color:${esc(f.color || '#64748b')}"></span>${esc(f.color || '-')}</td><td class="maker-money">${money(f.precioKilo)}</td><td>${status(f.activo)}</td><td>${admin ? kebab(f.id, 'filament') : ''}</td></tr>`).join('') : emptyRow(7, 'No hay filamentos')}</tbody></table></div></div>`; if (admin) document.getElementById('mkNewFilament').addEventListener('click', () => filamentModal()); bindCatalogActions('filament'); }
  function renderMaterials() { const admin = isAdmin(); document.getElementById('maker-materials').innerHTML = `<div class="maker-toolbar"><div><h5>Catálogo de materiales</h5><small>Administra los materiales base de tus filamentos</small></div>${admin ? '<button class="btn btn-primary" id="mkNewMaterial"><i class="fas fa-plus me-1"></i>Nuevo material</button>' : ''}</div><div class="panel-card overflow-hidden"><div class="table-responsive"><table class="table table-custom maker-table"><thead><tr><th>Nombre</th><th>Estado</th><th>Filamentos</th><th></th></tr></thead><tbody>${state.materials.length ? state.materials.map(m => `<tr><td><strong>${esc(m.nombre)}</strong></td><td>${status(m.activo)}</td><td>${state.filaments.filter(f => f.materialId === m.id).length}</td><td>${admin ? kebab(m.id, 'material') : ''}</td></tr>`).join('') : emptyRow(4, 'No hay materiales')}</tbody></table></div></div>`; if (admin) document.getElementById('mkNewMaterial').addEventListener('click', () => materialModal()); bindCatalogActions('material'); }
  const status = active => `<span class="maker-status ${active ? 'active' : 'inactive'}"><i class="fas fa-circle"></i>${active ? 'Activo' : 'Inactivo'}</span>`;
  const emptyRow = (span, text) => `<tr><td colspan="${span}"><div class="empty-state"><i class="fas fa-box-open"></i><p>${text}</p></div></td></tr>`;
  function bindCatalogActions(type) { document.querySelectorAll(`.maker-action[data-action="view-${type}"]`).forEach(b => b.addEventListener('click', () => { if (type === 'material') materialModal(Number(b.dataset.id)); else filamentModal(Number(b.dataset.id)); })); document.querySelectorAll(`.maker-action[data-action="delete-${type}"]`).forEach(b => b.addEventListener('click', async () => { if (await Utils.confirmAction('¿Desactivar este registro?', 'Confirmar', 'Desactivar')) { await API.del(`/maker/${type === 'material' ? 'materiales' : 'filamentos'}/${b.dataset.id}`); await refreshCatalogs(); Utils.showToast('Registro desactivado', 'success'); } })); }
  async function refreshCatalogs() { state.filaments = await API.get('/maker/filamentos?todos=true'); state.materials = await API.get('/maker/materiales?todos=true'); renderFilaments(); renderMaterials(); }
  function materialModal(id) { const item = id && state.materials.find(m => m.id === id); document.getElementById('makerCatalogTitle').textContent = item ? 'Editar material' : 'Nuevo material'; document.getElementById('makerCatalogBody').innerHTML = `<label class="form-label">Nombre <span class="text-danger">*</span></label><input id="mkModalName" class="form-control" value="${esc(item?.nombre || '')}" maxlength="100"><div class="form-check mt-3"><input id="mkModalActive" class="form-check-input" type="checkbox" ${item?.activo !== false ? 'checked' : ''}><label class="form-check-label">Activo</label></div>`; document.getElementById('makerCatalogSave').onclick = async () => { const name = document.getElementById('mkModalName').value.trim(); if (!name) return Utils.showToast('El nombre es obligatorio', 'warning'); try { await (id ? API.put(`/maker/materiales/${id}`, { nombre: name, activo: document.getElementById('mkModalActive').checked }) : API.post('/maker/materiales', { nombre: name, activo: true })); bootstrap.Modal.getInstance(document.getElementById('makerCatalogModal')).hide(); await refreshCatalogs(); Utils.showToast('Material guardado', 'success'); } catch (e) { Utils.showToast(e.message, 'error'); } }; new bootstrap.Modal(document.getElementById('makerCatalogModal')).show(); }
  function filamentModal(id) { const item = id && state.filaments.find(f => f.id === id); document.getElementById('makerCatalogTitle').textContent = item ? 'Editar filamento' : 'Nuevo filamento'; document.getElementById('makerCatalogBody').innerHTML = `<div class="row g-3"><div class="col-12"><label class="form-label">Nombre *</label><input id="mkModalName" class="form-control" value="${esc(item?.nombre || '')}"></div><div class="col-md-6"><label class="form-label">Material *</label><select id="mkModalMaterial" class="form-select">${state.materials.filter(m => m.activo || m.id === item?.materialId).map(m => `<option value="${m.id}" ${m.id === item?.materialId ? 'selected' : ''}>${esc(m.nombre)}</option>`).join('')}</select></div><div class="col-md-6"><label class="form-label">Precio por kilo *</label><input id="mkModalPrice" type="number" min="0" step="0.01" class="form-control" value="${item?.precioKilo || ''}"></div><div class="col-md-6"><label class="form-label">Marca</label><input id="mkModalBrand" class="form-control" value="${esc(item?.marca || '')}"></div><div class="col-md-6"><label class="form-label">Color</label><input id="mkModalColor" class="form-control" value="${esc(item?.color || '')}"></div><div class="col-12 form-check ms-2"><input id="mkModalActive" class="form-check-input" type="checkbox" ${item?.activo !== false ? 'checked' : ''}><label class="form-check-label">Activo</label></div></div>`; document.getElementById('makerCatalogSave').onclick = async () => { const data = { nombre: document.getElementById('mkModalName').value.trim(), materialId: Number(document.getElementById('mkModalMaterial').value), precioKilo: Number(document.getElementById('mkModalPrice').value), marca: document.getElementById('mkModalBrand').value.trim(), color: document.getElementById('mkModalColor').value.trim(), activo: document.getElementById('mkModalActive').checked }; if (!data.nombre || !data.materialId || data.precioKilo < 0) return Utils.showToast('Completa los campos obligatorios', 'warning'); try { await (id ? API.put(`/maker/filamentos/${id}`, data) : API.post('/maker/filamentos', data)); bootstrap.Modal.getInstance(document.getElementById('makerCatalogModal')).hide(); await refreshCatalogs(); Utils.showToast('Filamento guardado', 'success'); } catch (e) { Utils.showToast(e.message, 'error'); } }; new bootstrap.Modal(document.getElementById('makerCatalogModal')).show(); }

  function renderSettings() { const admin = isAdmin(); document.getElementById('maker-settings').innerHTML = `<div class="maker-toolbar"><div><h5>Configuración de costos</h5><small>Valores usados por la calculadora de Maker</small></div></div>${admin ? `<div class="maker-settings-grid">${['COSTO_KWH','CONSUMO_KW','MERMA_MONOCOLOR','MERMA_MULTICOLOR','PURGA_POR_CAMBIO','MARGEN_PUBLICO','MARGEN_MAYOREO','MARGEN_DISTRIBUIDOR'].map(key => `<div class="panel-card maker-setting-card"><div><span>${key.replaceAll('_', ' ')}</span><small>${settingLabel(key)}</small></div><div class="input-group"><input class="form-control mk-setting" data-key="${key}" type="number" min="0" step="0.01" value="${displaySetting(key)}"><button class="btn btn-outline-primary mk-save-setting" data-key="${key}" title="Guardar"><i class="fas fa-check"></i></button></div></div>`).join('')}</div>` : '<div class="empty-state"><i class="fas fa-lock"></i><p>Solo los administradores pueden modificar la configuración.</p></div>'}`; document.querySelectorAll('.mk-save-setting').forEach(b => b.addEventListener('click', async () => { try { const entered = Number(document.querySelector(`.mk-setting[data-key="${b.dataset.key}"]`).value); const value = isPercentSetting(b.dataset.key) ? entered / 100 : entered; await API.put('/maker/configuracion/' + b.dataset.key, { valor: value }); state.settings[b.dataset.key] = value; Utils.showToast('Configuración actualizada', 'success'); } catch (e) { Utils.showToast(e.message, 'error'); } })); }
  function isPercentSetting(key) { return key.startsWith('MERMA_') || key.startsWith('MARGEN_'); }
  function displaySetting(key) { return isPercentSetting(key) ? (setting(key) * 100).toFixed(2) : setting(key); }
  function settingLabel(key) { const labels = { COSTO_KWH: 'Costo de electricidad MXN/kWh', CONSUMO_KW: 'Consumo predeterminado de la A1', MERMA_MONOCOLOR: 'Porcentaje de merma monocolor', MERMA_MULTICOLOR: 'Porcentaje de merma multicolor', PURGA_POR_CAMBIO: 'Gramos de purga por cambio', MARGEN_PUBLICO: 'Margen de precio público', MARGEN_MAYOREO: 'Margen de precio mayoreo', MARGEN_DISTRIBUIDOR: 'Margen de precio distribuidor' }; return labels[key] || ''; }

  async function loadWorkspace() {
    bindTaskMentionAutofill();
    try {
      const [users, projects, tasks, quotes] = await Promise.all([
        API.get('/maker/usuarios'), API.get('/maker/proyectos?page=0&size=200'), API.get('/maker/tareas?page=0&size=200'), API.get('/maker/cotizaciones?page=0&size=200')
      ]);
      state.users = users || []; state.projects = projects?.content || []; state.tasks = tasks?.content || []; state.quotes = quotes?.content || [];
      renderProjects(); renderTasks();
    } catch (e) { Utils.showToast('No se pudo cargar el espacio de trabajo Maker: ' + e.message, 'error'); }
  }
  function bindTaskMentionAutofill() { if (state.mentionBound) return; state.mentionBound = true; document.addEventListener('change', e => { if (e.target.id !== 'mkTaskMentions') return; const description = document.getElementById('mkWorkDescription'); if (!description) return; const mentions = [...e.target.selectedOptions].map(o => '@' + o.textContent.replace(/^@/, '').trim()); const clean = (description.value || '').replace(/\n\nTareas mencionadas:[\s\S]*$/, '').trim(); description.value = mentions.length ? clean + '\n\nTareas mencionadas: ' + mentions.join(' ') : clean; }); }
  async function loadProjects() { try { const data = await API.get('/maker/proyectos?page=0&size=200'); state.projects = data.content || []; renderProjects(); } catch (e) { Utils.showToast(e.message, 'error'); } }
  async function loadTasks() { try { const data = await API.get('/maker/tareas?page=0&size=200'); state.tasks = data.content || []; renderTasks(); } catch (e) { Utils.showToast(e.message, 'error'); } }
  const stateLabel = value => ({ SIN_COMENZAR: 'Sin comenzar', EN_PROGRESO: 'En progreso', HECHO: 'Hecho', COTIZACION: 'Cotización', MUESTREO: 'Muestreo', PRODUCCION: 'Producción', ENTREGA: 'Entrega' }[value] || value);
  const projectStatuses = ['COTIZACION', 'MUESTREO', 'PRODUCCION', 'ENTREGA'];
  const priorityLabel = value => ({ BAJA: 'Baja', MEDIA: 'Media', ALTA: 'Alta', URGENTE: 'Urgente' }[value] || value);
  const priorityClass = value => 'maker-priority-' + String(value || '').toLowerCase();
  const avatarStack = users => (users || []).slice(0, 3).map(u => `<span class="maker-avatar" title="${esc(u.username)}">${esc((u.username || 'U').charAt(0).toUpperCase())}</span>`).join('') + ((users || []).length > 3 ? `<span class="maker-avatar maker-avatar-more">+${users.length - 3}</span>` : '');
  const workspaceKebab = (id, type) => `<div class="dropdown maker-card-menu"><button class="btn btn-icon" data-bs-toggle="dropdown" aria-label="Acciones"><i class="fas fa-ellipsis-vertical"></i></button><ul class="dropdown-menu dropdown-menu-end"><li><button class="dropdown-item maker-work-action" data-action="view-${type}" data-id="${id}"><i class="fas fa-eye me-2"></i>Ver detalle</button></li><li><button class="dropdown-item maker-work-action" data-action="edit-${type}" data-id="${id}"><i class="fas fa-pen me-2"></i>Editar</button></li><li><button class="dropdown-item text-danger maker-work-action" data-action="delete-${type}" data-id="${id}"><i class="fas fa-trash me-2"></i>Eliminar</button></li></ul></div>`;
  function renderProjects() {
    const statuses = projectStatuses; const box = document.getElementById('maker-projects'); if (!box) return;
    box.innerHTML = `<div class="maker-toolbar"><div><h5>Proyectos de impresión</h5><small>Organiza tus trabajos como un tablero visual</small></div><button class="btn btn-primary" id="mkNewProject"><i class="fas fa-plus me-1"></i>Nuevo proyecto</button></div><div class="maker-kanban maker-kanban-projects">${statuses.map(status => `<div class="maker-column" data-project-status="${status}"><div class="maker-column-head"><div><span class="maker-column-dot ${status.toLowerCase()}"></span><strong>${stateLabel(status)}</strong></div><span class="maker-column-count">${state.projects.filter(p => p.estado === status).length}</span></div><div class="maker-column-body">${state.projects.filter(p => p.estado === status).map(projectCard).join('')}</div></div>`).join('')}</div>`;
    document.getElementById('mkNewProject').addEventListener('click', () => projectModal()); bindWorkspaceActions(); bindProjectDnD();
  }
  function projectCard(p) { const progress = p.tareasTotal ? Math.round((p.tareasHechas / p.tareasTotal) * 100) : 0; return `<article class="maker-board-card" draggable="true" data-project-id="${p.id}" style="--card-color:${esc(p.color || '#00ff41')}"><div class="maker-card-top"><span class="maker-priority ${priorityClass(p.prioridad)}">${priorityLabel(p.prioridad)}</span>${workspaceKebab(p.id, 'project')}</div><button class="maker-card-title maker-open-project" data-id="${p.id}">${esc(p.nombre)}</button><p>${esc(p.descripcion || 'Sin descripción')}</p><div class="maker-card-meta">${p.fechaFin ? `<span><i class="far fa-calendar me-1"></i>${Utils.formatDate(p.fechaFin)}</span>` : '<span>Sin fecha límite</span>'}<span>${p.cotizacionFolio ? `<i class="fas fa-receipt me-1"></i>${esc(p.cotizacionFolio)}` : '<i class="fas fa-receipt me-1"></i>Sin cotización'}</span></div><div class="maker-card-bottom"><div class="maker-avatar-stack">${avatarStack(p.asignados)}</div><span class="maker-task-progress"><i class="fas fa-list-check me-1"></i>${p.tareasHechas}/${p.tareasTotal} · ${progress}%</span></div></article>`; }
  function bindProjectDnD() { document.querySelectorAll('[data-project-status]').forEach(column => { column.addEventListener('dragover', e => { e.preventDefault(); column.classList.add('drag-over'); }); column.addEventListener('dragleave', () => column.classList.remove('drag-over')); column.addEventListener('drop', async e => { e.preventDefault(); column.classList.remove('drag-over'); const id = Number(e.dataTransfer.getData('project-id')); const project = state.projects.find(p => p.id === id); if (!project || project.estado === column.dataset.projectStatus) return; await saveProjectPayload(project, { estado: column.dataset.projectStatus }); }); }); document.querySelectorAll('[data-project-id]').forEach(card => card.addEventListener('dragstart', e => e.dataTransfer.setData('project-id', card.dataset.projectId))); }
  function renderTasks() { const statuses = ['SIN_COMENZAR', 'EN_PROGRESO', 'HECHO']; const box = document.getElementById('maker-tasks'); if (!box) return; box.innerHTML = `<div class="maker-toolbar"><div><h5>Tareas Maker</h5><small>Arrastra tareas entre estados y trabaja en equipo</small></div><button class="btn btn-primary" id="mkNewTask"><i class="fas fa-plus me-1"></i>Nueva tarea</button></div><div class="maker-kanban maker-kanban-tasks">${statuses.map(status => `<div class="maker-column" data-task-status="${status}"><div class="maker-column-head"><div><span class="maker-column-dot ${status.toLowerCase()}"></span><strong>${stateLabel(status)}</strong></div><span class="maker-column-count">${state.tasks.filter(t => t.estado === status).length}</span></div><div class="maker-column-body">${state.tasks.filter(t => t.estado === status).map(taskCard).join('')}</div></div>`).join('')}</div>`; document.getElementById('mkNewTask').addEventListener('click', () => taskModal()); bindWorkspaceActions(); bindTaskDnD(); }
  function taskCard(t) { return `<article class="maker-board-card" draggable="true" data-task-id="${t.id}" style="--card-color:${esc(t.color || '#00ff41')}"><div class="maker-card-top"><span class="maker-priority ${priorityClass(t.prioridad)}">${priorityLabel(t.prioridad)}</span>${workspaceKebab(t.id, 'task')}</div><button class="maker-card-title maker-open-task" data-id="${t.id}">${esc(t.nombre)}</button><p>${esc(t.descripcion || 'Sin descripción')}</p><div class="maker-card-meta">${t.proyectoNombre ? `<span><i class="fas fa-diagram-project me-1"></i>${esc(t.proyectoNombre)}</span>` : '<span>Tarea general</span>'}${t.fechaFin ? `<span><i class="far fa-calendar me-1"></i>${Utils.formatDate(t.fechaFin)}</span>` : ''}</div><div class="maker-card-bottom"><div class="maker-avatar-stack">${avatarStack(t.asignados)}</div><span class="maker-task-progress"><i class="fas fa-at me-1"></i>${(t.tareasMencionadas || []).length}</span></div></article>`; }
  function bindTaskDnD() { document.querySelectorAll('[data-task-status]').forEach(column => { column.addEventListener('dragover', e => { e.preventDefault(); column.classList.add('drag-over'); }); column.addEventListener('dragleave', () => column.classList.remove('drag-over')); column.addEventListener('drop', async e => { e.preventDefault(); column.classList.remove('drag-over'); const id = Number(e.dataTransfer.getData('task-id')); const task = state.tasks.find(t => t.id === id); if (!task || task.estado === column.dataset.taskStatus) return; await saveTaskPayload(task, { estado: column.dataset.taskStatus }); }); }); document.querySelectorAll('[data-task-id]').forEach(card => card.addEventListener('dragstart', e => e.dataTransfer.setData('task-id', card.dataset.taskId))); }
  function bindWorkspaceActions() { document.querySelectorAll('.maker-open-project').forEach(b => b.addEventListener('click', () => projectDetail(Number(b.dataset.id)))); document.querySelectorAll('.maker-open-task').forEach(b => b.addEventListener('click', () => taskDetail(Number(b.dataset.id)))); document.querySelectorAll('.maker-work-action').forEach(b => b.addEventListener('click', async () => { const id = Number(b.dataset.id); const action = b.dataset.action; if (action === 'view-project') projectDetail(id); if (action === 'edit-project') projectModal(id); if (action === 'view-task') taskDetail(id); if (action === 'edit-task') taskModal(id); if (action === 'delete-project' || action === 'delete-task') { if (!await Utils.confirmAction('¿Eliminar este registro?', 'Confirmar', 'Eliminar')) return; await API.del(`/maker/${action.endsWith('project') ? 'proyectos' : 'tareas'}/${id}`); Utils.showToast('Registro eliminado', 'success'); await loadWorkspace(); } })); }
  function multiOptions(items, selected = []) { return items.map(i => `<option value="${i.id}" ${selected.includes(i.id) ? 'selected' : ''}>${esc(i.username || i.nombre)}</option>`).join(''); }
  function projectSelect(selected) { return '<option value="">Sin proyecto</option>' + state.projects.map(p => `<option value="${p.id}" ${p.id === selected ? 'selected' : ''}>${esc(p.nombre)}</option>`).join(''); }
  function colorInput(value) { return `<input id="mkWorkColor" type="color" class="form-control form-control-color" value="${esc(value || '#00ff41')}" title="Color de tarjeta">`; }
  function projectModal(id) { const p = id && state.projects.find(x => x.id === id); document.getElementById('makerCatalogTitle').textContent = p ? 'Editar proyecto' : 'Nuevo proyecto'; document.getElementById('makerCatalogBody').innerHTML = `<div class="row g-3"><div class="col-12"><label class="form-label">Nombre *</label><input id="mkWorkName" class="form-control" value="${esc(p?.nombre || '')}"></div><div class="col-12"><label class="form-label">Sobre el proyecto</label><textarea id="mkWorkDescription" class="form-control" rows="3" placeholder="Describe el objetivo, medidas o contexto">${esc(p?.descripcion || '')}</textarea></div><div class="col-md-6"><label class="form-label">Estado</label><select id="mkWorkStatus" class="form-select">${projectStatusOptions(p?.estado)}</select></div><div class="col-md-6"><label class="form-label">Prioridad</label><select id="mkWorkPriority" class="form-select">${priorityOptions(p?.prioridad)}</select></div><div class="col-md-6"><label class="form-label">Fecha límite</label><input id="mkWorkDate" type="date" class="form-control" value="${p?.fechaFin || ''}"></div><div class="col-md-6"><label class="form-label">Color</label>${colorInput(p?.color)}</div><div class="col-12"><label class="form-label">Usuarios asignados</label><select id="mkWorkUsers" class="form-select" multiple>${multiOptions(state.users, (p?.asignados || []).map(u => u.id))}</select><div class="form-text">Usa Ctrl/Cmd para seleccionar varios usuarios.</div></div><div class="col-12"><label class="form-label">Cotización vinculada</label><select id="mkWorkQuote" class="form-select"><option value="">Sin cotización</option>${state.quotes.map(q => `<option value="${q.id}" ${q.id === p?.cotizacionId ? 'selected' : ''}>${esc(q.folio)} · ${esc(q.descripcion || 'Sin descripción')}</option>`).join('')}</select></div></div>`; document.getElementById('makerCatalogSave').onclick = async () => { const request = { nombre: document.getElementById('mkWorkName').value.trim(), descripcion: document.getElementById('mkWorkDescription').value.trim(), estado: document.getElementById('mkWorkStatus').value, prioridad: document.getElementById('mkWorkPriority').value, color: document.getElementById('mkWorkColor').value, fechaFin: document.getElementById('mkWorkDate').value || null, cotizacionId: Number(document.getElementById('mkWorkQuote').value) || null, usuarioIds: [...document.getElementById('mkWorkUsers').selectedOptions].map(o => Number(o.value)) }; if (!request.nombre) return Utils.showToast('El nombre es obligatorio', 'warning'); try { await saveProjectPayload(p, request, id); bootstrap.Modal.getInstance(document.getElementById('makerCatalogModal')).hide(); await loadWorkspace(); Utils.showToast('Proyecto guardado', 'success'); } catch (e) { Utils.showToast(e.message, 'error'); } }; new bootstrap.Modal(document.getElementById('makerCatalogModal')).show(); }
  function statusOptions(selected) { return [['SIN_COMENZAR', 'Sin comenzar'], ['EN_PROGRESO', 'En progreso'], ['HECHO', 'Hecho']].map(x => `<option value="${x[0]}" ${x[0] === (selected || 'SIN_COMENZAR') ? 'selected' : ''}>${x[1]}</option>`).join(''); }
  function projectStatusOptions(selected) { return projectStatuses.map(x => `<option value="${x}" ${x === (selected || 'COTIZACION') ? 'selected' : ''}>${stateLabel(x)}</option>`).join(''); }
  function priorityOptions(selected) { return [['BAJA', 'Baja'], ['MEDIA', 'Media'], ['ALTA', 'Alta'], ['URGENTE', 'Urgente']].map(x => `<option value="${x[0]}" ${x[0] === (selected || 'MEDIA') ? 'selected' : ''}>${x[1]}</option>`).join(''); }
  async function saveProjectPayload(p, request, id = p?.id) { const payload = { ...request, nombre: request.nombre || p.nombre, descripcion: request.descripcion ?? p.descripcion, estado: request.estado || p.estado, prioridad: request.prioridad || p.prioridad, color: request.color || p.color, fechaFin: request.fechaFin ?? p.fechaFin, cotizacionId: request.cotizacionId ?? p.cotizacionId, usuarioIds: request.usuarioIds || (p.asignados || []).map(u => u.id) }; await (id ? API.put('/maker/proyectos/' + id, payload) : API.post('/maker/proyectos', payload)); await loadWorkspace(); }
  function taskModal(id, projectId = null) { const t = id && state.tasks.find(x => x.id === id); document.getElementById('makerCatalogTitle').textContent = t ? 'Editar tarea' : 'Nueva tarea'; document.getElementById('makerCatalogBody').innerHTML = `<div class="row g-3"><div class="col-12"><label class="form-label">Nombre *</label><input id="mkWorkName" class="form-control" value="${esc(t?.nombre || '')}"></div><div class="col-12"><label class="form-label">Descripción</label><textarea id="mkWorkDescription" class="form-control" rows="3" placeholder="Describe la tarea; puedes escribir @ para indicar una referencia">${esc(t?.descripcion || '')}</textarea></div><div class="col-12"><label class="form-label">Checklist / subtareas</label><textarea id="mkTaskChecklist" class="form-control" rows="4" placeholder="Una subtarea por línea, por ejemplo: [ ] Preparar archivo">${esc(t?.checklist || '')}</textarea><div class="form-text">Escribe una subtarea por línea usando [ ] o [x].</div></div><div class="col-md-6"><label class="form-label">Estado</label><select id="mkWorkStatus" class="form-select">${statusOptions(t?.estado)}</select></div><div class="col-md-6"><label class="form-label">Prioridad</label><select id="mkWorkPriority" class="form-select">${priorityOptions(t?.prioridad)}</select></div><div class="col-md-6"><label class="form-label">Fecha límite</label><input id="mkWorkDate" type="date" class="form-control" value="${t?.fechaFin || ''}"></div><div class="col-md-6"><label class="form-label">Color</label>${colorInput(t?.color)}</div><div class="col-md-6"><label class="form-label">Proyecto</label><select id="mkTaskProject" class="form-select">${projectSelect(t?.proyectoId || projectId)}</select></div><div class="col-md-6"><label class="form-label">Usuarios asignados</label><select id="mkWorkUsers" class="form-select" multiple>${multiOptions(state.users, (t?.asignados || []).map(u => u.id))}</select></div><div class="col-md-6"><label class="form-label">Mencionar tareas con @</label><select id="mkTaskMentions" class="form-select" multiple>${state.tasks.filter(x => x.id !== id).map(x => `<option value="${x.id}" ${(t?.tareasMencionadas || []).some(m => m.id === x.id) ? 'selected' : ''}>@${esc(x.nombre)}</option>`).join('')}</select></div><div class="col-md-6"><label class="form-label">Mencionar usuarios con @</label><select id="mkTaskMentionUsers" class="form-select" multiple>${multiOptions(state.users, [])}</select></div></div>`; document.getElementById('makerCatalogSave').onclick = async () => { const request = { nombre: document.getElementById('mkWorkName').value.trim(), descripcion: document.getElementById('mkWorkDescription').value.trim(), checklist: document.getElementById('mkTaskChecklist').value, estado: document.getElementById('mkWorkStatus').value, prioridad: document.getElementById('mkWorkPriority').value, color: document.getElementById('mkWorkColor').value, fechaFin: document.getElementById('mkWorkDate').value || null, proyectoId: Number(document.getElementById('mkTaskProject').value) || null, usuarioIds: [...document.getElementById('mkWorkUsers').selectedOptions].map(o => Number(o.value)), tareasMencionadasIds: [...document.getElementById('mkTaskMentions').selectedOptions].map(o => Number(o.value)), usuariosMencionadosIds: [...document.getElementById('mkTaskMentionUsers').selectedOptions].map(o => Number(o.value)) }; if (!request.nombre) return Utils.showToast('El nombre es obligatorio', 'warning'); try { await saveTaskPayload(t, request, id); bootstrap.Modal.getInstance(document.getElementById('makerCatalogModal')).hide(); Utils.showToast('Tarea guardada', 'success'); } catch (e) { Utils.showToast(e.message, 'error'); } }; new bootstrap.Modal(document.getElementById('makerCatalogModal')).show(); }
  async function saveTaskPayload(t, request, id = t?.id) { const payload = { ...request, nombre: request.nombre || t.nombre, descripcion: request.descripcion ?? t.descripcion, checklist: request.checklist ?? t.checklist, estado: request.estado || t.estado, prioridad: request.prioridad || t.prioridad, color: request.color || t.color, fechaFin: request.fechaFin ?? t.fechaFin, proyectoId: request.proyectoId ?? t.proyectoId, usuarioIds: request.usuarioIds || (t.asignados || []).map(u => u.id), tareasMencionadasIds: request.tareasMencionadasIds || (t.tareasMencionadas || []).map(x => x.id), usuariosMencionadosIds: request.usuariosMencionadosIds || [] }; await (id ? API.put('/maker/tareas/' + id, payload) : API.post('/maker/tareas', payload)); await loadWorkspace(); }
  async function projectDetail(id) { const p = await API.get('/maker/proyectos/' + id); const tasks = await API.get('/maker/proyectos/' + id + '/tareas'); document.getElementById('makerDetailBody').innerHTML = `<div class="maker-project-detail-head" style="--card-color:${esc(p.color)}"><div><span class="maker-priority ${priorityClass(p.prioridad)}">${priorityLabel(p.prioridad)}</span><h3>${esc(p.nombre)}</h3><p>${esc(p.descripcion || 'Sin descripción')}</p></div><div>${workspaceKebab(p.id, 'project')}</div></div><div class="maker-detail-grid"><div><small>Estado</small><strong>${stateLabel(p.estado)}</strong></div><div><small>Fecha límite</small><strong>${p.fechaFin ? Utils.formatDate(p.fechaFin) : 'Sin fecha'}</strong></div><div><small>Progreso</small><strong>${p.tareasHechas}/${p.tareasTotal} tareas</strong></div></div><div class="maker-detail-actions"><button class="btn btn-primary" data-work-action="new-task-project" data-id="${p.id}"><i class="fas fa-plus me-1"></i>Nueva tarea</button><button class="btn btn-outline-primary" data-work-action="quote-project" data-id="${p.id}"><i class="fas fa-receipt me-1"></i>Cotizar proyecto</button></div><hr><h6>Action items</h6><div class="maker-project-task-list">${tasks.length ? tasks.map(t => `<button class="maker-detail-task" data-work-action="view-task" data-id="${t.id}"><span class="maker-column-dot ${t.estado.toLowerCase()}"></span>${esc(t.nombre)}<small>${stateLabel(t.estado)}</small></button>`).join('') : '<div class="text-muted small">Aún no hay tareas en este proyecto.</div>'}</div>`; document.getElementById('makerDetailBody').insertAdjacentHTML('beforeend', '<hr><h6>Kanban del proyecto</h6>' + inlineProjectBoard(tasks)); document.querySelectorAll('#makerDetailBody [data-inline-task-id]').forEach(b => b.addEventListener('click', () => taskDetail(Number(b.dataset.inlineTaskId)))); bindInlineProjectDnD(tasks); const modal = new bootstrap.Modal(document.getElementById('makerDetailModal')); modal.show(); document.querySelectorAll('#makerDetailBody [data-work-action]').forEach(b => b.addEventListener('click', () => { if (b.dataset.workAction === 'view-task') { modal.hide(); taskDetail(Number(b.dataset.id)); } if (b.dataset.workAction === 'new-task-project') { modal.hide(); taskModal(null, Number(b.dataset.id)); } if (b.dataset.workAction === 'quote-project') { modal.hide(); state.quoteProjectId = Number(b.dataset.id); document.querySelector('[data-maker-tab="calculator"]')?.click(); Utils.showToast('La siguiente cotización quedará vinculada al proyecto', 'info'); } })); }
  async function taskDetail(id) { const t = await API.get('/maker/tareas/' + id); const checklist = checklistHtml(t); document.getElementById('makerDetailBody').innerHTML = `<div class="maker-project-detail-head" style="--card-color:${esc(t.color)}"><div><span class="maker-priority ${priorityClass(t.prioridad)}">${priorityLabel(t.prioridad)}</span><h3>${esc(t.nombre)}</h3><p>${esc(t.descripcion || 'Sin descripción')}</p></div><div>${workspaceKebab(t.id, 'task')}</div></div><div class="maker-detail-grid"><div><small>Estado</small><strong>${stateLabel(t.estado)}</strong></div><div><small>Proyecto</small><strong>${esc(t.proyectoNombre || 'General')}</strong></div><div><small>Fecha límite</small><strong>${t.fechaFin ? Utils.formatDate(t.fechaFin) : 'Sin fecha'}</strong></div></div><hr><h6>Checklist</h6><div class="maker-checklist">${checklist || '<span class="text-muted small">No hay subtareas agregadas.</span>'}</div><hr><h6>Menciones de tareas</h6><div class="maker-mention-list">${(t.tareasMencionadas || []).length ? t.tareasMencionadas.map(m => `<span class="maker-mention">@${esc(m.nombre)}</span>`).join('') : '<span class="text-muted small">Sin tareas mencionadas</span>'}</div>`; new bootstrap.Modal(document.getElementById('makerDetailModal')).show(); document.querySelectorAll('#makerDetailBody .maker-check-item').forEach(c => c.addEventListener('change', () => toggleChecklist(t, Number(c.dataset.index), c.checked))); }
  function checklistHtml(t) { return String(t.checklist || '').split('\n').filter(Boolean).map((line, index) => { const checked = /^\s*\[x\]/i.test(line); const label = line.replace(/^\s*\[[ x]\]\s*/i, ''); return `<label class="maker-check-item"><input type="checkbox" data-index="${index}" ${checked ? 'checked' : ''}><span>${esc(label)}</span></label>`; }).join(''); }
  async function toggleChecklist(t, index, checked) { const lines = String(t.checklist || '').split('\n'); if (!lines[index]) return; lines[index] = lines[index].replace(/^\s*\[[ x]\]/i, checked ? '[x]' : '[ ]'); await saveTaskPayload(t, { checklist: lines.join('\n') }, t.id); }
  function inlineProjectBoard(tasks) { return `<div class="maker-kanban maker-inline-kanban">${['SIN_COMENZAR', 'EN_PROGRESO', 'HECHO'].map(status => `<div class="maker-column" data-inline-task-status="${status}"><div class="maker-column-head"><div><span class="maker-column-dot ${status.toLowerCase()}"></span><strong>${stateLabel(status)}</strong></div><span class="maker-column-count">${tasks.filter(t => t.estado === status).length}</span></div><div class="maker-column-body">${tasks.filter(t => t.estado === status).map(t => `<button class="maker-inline-task" draggable="true" data-inline-task-id="${t.id}"><span class="maker-column-dot ${t.estado.toLowerCase()}"></span>${esc(t.nombre)}<small>${priorityLabel(t.prioridad)}</small></button>`).join('')}</div></div>`).join('')}</div>`; }
  function bindInlineProjectDnD(tasks) { document.querySelectorAll('#makerDetailBody [data-inline-task-status]').forEach(column => { column.addEventListener('dragover', e => e.preventDefault()); column.addEventListener('drop', async e => { e.preventDefault(); const task = tasks.find(t => t.id === Number(e.dataTransfer.getData('inline-task-id'))); if (task && task.estado !== column.dataset.inlineTaskStatus) { await saveTaskPayload(task, { estado: column.dataset.inlineTaskStatus }, task.id); Utils.showToast('Estado actualizado', 'success'); projectDetail(task.proyectoId); } }); }); document.querySelectorAll('#makerDetailBody [data-inline-task-id]').forEach(card => { card.setAttribute('draggable', 'true'); card.addEventListener('dragstart', e => e.dataTransfer.setData('inline-task-id', card.dataset.inlineTaskId)); }); }
  return { init };
})();
export function init() { return Maker.init(); }
